source_lines, start_line = inspect.getsourcelines(call_event_handler)
source = ''.join(source_lines)
tree = ast.parse(source)
fn = next(n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name=='call_event_handler')
param_def_lines = {}
for a in fn.args.args:
    if a.arg in tracked:
        param_def_lines[a.arg] = start_line + a.lineno - 1

instr_map = {ins.offset: ins for ins in dis.get_instructions(call_event_handler)}

pairs = set()
current_def = {}
call_depth = 0

def tracer(frame, event, arg):
    global call_depth
    if event == 'call':
        if frame.f_code is call_event_handler.__code__:
            frame.f_trace_opcodes = True
            frame.f_trace_lines = True
            current_def.clear()
            current_def.update(param_def_lines)
            return tracer
        return tracer

    if frame.f_code is not call_event_handler.__code__:
        return tracer

    if event == 'opcode':
        ins = instr_map.get(frame.f_lasti)
        if ins is None:
            return tracer
        op = ins.opname
        var = ins.argval if isinstance(ins.argval, str) else None
        line = frame.f_lineno

        if var in tracked:
            if op.startswith('LOAD_'):
                d = current_def.get(var)
                if d is not None:
                    pairs.add((var, d, line))
            elif op.startswith('STORE_'):
                current_def[var] = line
            elif op.startswith('DELETE_'):
                current_def.pop(var, None)
    return tracer

sys.settrace(tracer)
try:
    qa_handler.__qualname__ = 'qa_handler'
    handler = EventHandler(fn=qa_handler, state_full_name='QAState')
    event_spec = call_event_handler(handler, [qa_spec_mismatch, qa_spec_match], key='on_change')
finally:
    sys.settrace(None)

for row in sorted(pairs, key=lambda x: (x[0], x[1], x[2])):
    print(row)
